WITH CONTAS_GRUPO AS (     SELECT         NTE.ID,         NTE.REFERENCIA,         NTE.CODEMP,         NTE_DET.ID AS ID_GRU,         NTE_DET.NOTA,         NTE_DET_GRU.ID AS ID_GRUPO,         NTE_DET_GRU.DESCRICAO,         NTE_CTB_REF.ID AS ID_NOTAS_EXPLICATIVAS_GRUPOS_REFER,         NTE_CTB_REF.REFERENCIA AS REFERENCIA_GRUPO,         NTE_CTB.PADRAO_CTACTB,         NTE_CTB.SINAL     FROM NOTAS_EXPLICATIVAS_CAB NTE     INNER JOIN NOTAS_EXPLICATIVAS_DET NTE_DET         ON NTE.ID = NTE_DET.ID_NOTAS_EXPLICATIVAS_CAB     INNER JOIN NOTAS_EXPLICATIVAS_GRUPOS NTE_DET_GRU         ON NTE_DET.ID = NTE_DET_GRU.ID_NOTAS_EXPLICATIVAS_DET     INNER JOIN NOTAS_EXPLICATIVAS_GRUPOS_REFER NTE_CTB_REF         ON NTE_DET_GRU.ID = NTE_CTB_REF.ID_NOTAS_EXPLICATIVAS_GRUPOS     INNER JOIN NOTAS_EXPLICATIVAS_GRUPOS_CONTAS NTE_CTB         ON NTE_CTB_REF.ID = NTE_CTB.ID_NOTAS_EXPLICATIVAS_GRUPOS_REFER     WHERE         NTE.CODEMP = :VAR_EMPRESA_DRE         AND NTE.REFERENCIA <= :VAR_DATA_REF_DRE ),  BALANCETE AS (     SELECT         CODEMP,         CTACTB,         REFERENCIA,         SUM(VLRLANC) AS VLRLANC     FROM IMP_BASE_BALANCETE     WHERE CODEMP = :VAR_EMPRESA_DRE     GROUP BY         CODEMP,         CTACTB,         REFERENCIA ),  BASE AS (     SELECT         CG.ID,         CG.REFERENCIA,         CG.CODEMP,         CG.ID_GRU,         CG.NOTA,         CG.ID_GRUPO,         CG.DESCRICAO,         CG.REFERENCIA_GRUPO,         YEAR(CG.REFERENCIA_GRUPO) AS ANO_GRUPO,          (             COALESCE(SUM(BAL.VLRLANC), 0) * CG.SINAL         ) / 1000 AS VALOR      FROM CONTAS_GRUPO CG      LEFT JOIN BALANCETE BAL         ON BAL.CODEMP = CG.CODEMP         AND BAL.CTACTB = CG.PADRAO_CTACTB          AND (              (                 (                     CG.PADRAO_CTACTB LIKE '3%'                     OR CG.PADRAO_CTACTB LIKE '4%'                     OR CG.PADRAO_CTACTB LIKE '5%'                 )                  AND YEAR(BAL.REFERENCIA) = YEAR(CG.REFERENCIA_GRUPO)                 AND BAL.REFERENCIA <= CG.REFERENCIA_GRUPO             )              OR              (                 CG.PADRAO_CTACTB NOT LIKE '3%'                 AND CG.PADRAO_CTACTB NOT LIKE '4%'                 AND CG.PADRAO_CTACTB NOT LIKE '5%'                 AND BAL.REFERENCIA <= CG.REFERENCIA_GRUPO             )          )      GROUP BY         CG.ID,         CG.REFERENCIA,         CG.CODEMP,         CG.ID_GRU,         CG.NOTA,         CG.ID_GRUPO,         CG.DESCRICAO,         CG.REFERENCIA_GRUPO,         CG.SINAL )  SELECT     BASE.ID,     BASE.REFERENCIA,     BASE.CODEMP,     BASE.ID_GRU,     BASE.NOTA,     BASE.DESCRICAO,      SUM(         CASE             WHEN BASE.ANO_GRUPO = YEAR(:VAR_DATA_REF_DRE)             THEN BASE.VALOR             ELSE 0         END     ) AS VALOR_ANO_ATUAL,      SUM(         CASE             WHEN BASE.ANO_GRUPO =                  YEAR(DATE_SUB(:VAR_DATA_REF_DRE, INTERVAL 1 YEAR))             THEN BASE.VALOR             ELSE 0         END     ) AS VALOR_ANO_ANTERIOR  FROM BASE  GROUP BY     BASE.ID,     BASE.REFERENCIA,     BASE.CODEMP,     BASE.ID_GRU,     BASE.NOTA,     BASE.DESCRICAO  ORDER BY     CAST(         SUBSTRING_INDEX(             CONCAT(BASE.NOTA, '.0.0.0'),             '.',             1         ) AS UNSIGNED     ),      CAST(         SUBSTRING_INDEX(             SUBSTRING_INDEX(                 CONCAT(BASE.NOTA, '.0.0.0'),                 '.',                 2             ),             '.',             -1         ) AS UNSIGNED     ),      CAST(         SUBSTRING_INDEX(             SUBSTRING_INDEX(                 CONCAT(BASE.NOTA, '.0.0.0'),                 '.',                 3             ),             '.',             -1         ) AS UNSIGNED     ),      CAST(         SUBSTRING_INDEX(             SUBSTRING_INDEX(                 CONCAT(BASE.NOTA, '.0.0.0'),                 '.',                 4             ),             '.',             -1         ) AS UNSIGNED     ),      BASE.ID_GRUPO;